        ];

        // Initialize counters for member numbering
        $memberCounter = 1;
        $familyCounter = 1;
        $familyGroups = [];
        
        // Process each member with proper numbering
        foreach ($members as $index => $member) {
            // Generate family_no based on old_family_no
            $oldFamilyNo = $member['old_family_no'] ?? '1';
            
            if (!isset($familyGroups[$oldFamilyNo])) {
                $familyGroups[$oldFamilyNo] = $familyCounter;
                $familyCounter++;
            }
            
            $familyGroup = str_pad($familyGroups[$oldFamilyNo], 3, '0', STR_PAD_LEFT);
            $memberSequence = str_pad($memberCounter, 3, '0', STR_PAD_LEFT);
            
            // Generate family_no: SAL-XXX-YYY
            $familyNo = "SAL-{$familyGroup}-{$memberSequence}";
            
            // Generate member_no: YYYY-SAL-MNNNNN
            $memberNo = "2025-SAL-M" . str_pad($memberCounter, 6, '0', STR_PAD_LEFT);
            
            // Update member data with new numbering
            $members[$index] = array_merge($member, [
                'family_no' => $familyNo,
                'member_no' => $memberNo,
                'registration_year' => '2025',
                'church_code' => 'SAL',
                'family_sequence' => (int) $familyGroup,
                'member_sequence' => $memberCounter,
                'marital_status' => 'single'
            ]);
            
            $memberCounter++;
        }
        
        // Insert members in chunks
        $chunks = array_chunk($members, 500);
        foreach ($chunks as $chunk) {
            DB::table('members')->insert($chunk);
        }
    }
